# Archive image‑analysis artifacts and derived captions in managed object storage (Amazon S3)\nimport os\nimport json\nimport boto3\nfrom datetime import datetime\n\nclass ImageAssetArchive:\n    \"\"\"Archive analysis results (labels, description, safety, captions) to S3.\n    \"\"\"\n    @staticmethod\n    def upload(analysis: dict, bucket_name: str, prefix: str = \"images\"):\n        \"\"\"Upload a JSON payload and any associated image files to S3.\n        Args:\n            analysis (dict): Dictionary with keys such as labels, description, safety, captions.\n            bucket_name (str): Name of the S3 bucket.\n            prefix (str): Optional folder prefix inside the bucket.\n        \"\"\"\n        s3 = boto3.client(\"s3\")\n        # Create a deterministic key using timestamp and a short hash of the analysis\n        ts = datetime.utcnow().strftime(\"%Y%m%dT%H%M%SZ\")\n        # Simple hash for uniqueness (any hash algorithm works)\n        h = abs(hash(json.dumps(analysis))) % (10 ** 8)\n        key = f\"{prefix}/{ts}_{h:08d}.json\"\n        # Convert analysis dict to JSON string\n        payload = json.dumps(analysis, indent=2)\n        # Upload the JSON payload\n        s3.put_object(Bucket=bucket_name, Key=key, Body=payload.encode('utf-8'))\n        return f\"s3://{bucket_name}/{key}\"\n\n# -----------------------------------------------------------------------------\n# End of image_asset_archive.py\n# -----------------------------------------------------------------------------
